begin;
select no_plan();
select has_table('public','customer_sources','mapeamento fonte e ID existe');
select has_table('public','operational_locations','locais operacionais existem');
insert into auth.users(id)values('60000000-0000-0000-0000-000000000001'),('60000000-0000-0000-0000-000000000002');
insert into public.profiles values('60000000-0000-0000-0000-000000000001','owner'),('60000000-0000-0000-0000-000000000002','driver');
select throws_ok($$insert into public.operational_locations(id,name,address,confirmed)values(gen_random_uuid(),'Local inválido',null,true)$$,'23514',null,'local confirmado exige endereço também na constraint');
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000001',true);
set local role authenticated;
select is(public.prepare_customer_import('61000000-0000-0000-0000-000000000001','fonte-teste','[{"sourceId":"a","name":"Cliente A","phone":"81999990000","address":"Rua fictícia","weekday":4,"position":1,"eggsPerTray":15,"trays":1},{"sourceId":"a","name":"Cliente A","phone":"81999990000","address":"Rua fictícia","weekday":4,"position":1,"eggsPerTray":30,"trays":2},{"sourceId":"b","name":"Cliente B","phone":"81999990000","address":"Rua B","weekday":4,"position":2,"eggsPerTray":20,"trays":1}]')->>'created','2','prévia agrupa produtos e não une telefone compartilhado');
select is((select count(*)from public.customers where name in('Cliente A','Cliente B')),0::bigint,'prévia não grava clientes');
select is(public.commit_customer_import('61000000-0000-0000-0000-000000000001','[{"sourceId":"a","name":"Cliente A","phone":"81999990000","address":"Rua fictícia","weekday":4,"position":1,"eggsPerTray":15,"trays":1},{"sourceId":"a","name":"Cliente A","phone":"81999990000","address":"Rua fictícia","weekday":4,"position":1,"eggsPerTray":30,"trays":2},{"sourceId":"b","name":"Cliente B","phone":"81999990000","address":"Rua B","weekday":4,"position":2,"eggsPerTray":20,"trays":1}]','62000000-0000-0000-0000-000000000001'),'{"created":2,"updated":0,"rejected":0}'::jsonb,'confirmação cria dois clientes atomicamente');
select is((select count(*)from public.standing_order_items where customer_id=(select customer_id from public.customer_sources where source='fonte-teste' and source_id='a')),2::bigint,'produtos distintos formam um cliente');
select is(public.commit_customer_import('61000000-0000-0000-0000-000000000001','[{"sourceId":"a","name":"Cliente A","phone":"81999990000","address":"Rua fictícia","weekday":4,"position":1,"eggsPerTray":15,"trays":1},{"sourceId":"a","name":"Cliente A","phone":"81999990000","address":"Rua fictícia","weekday":4,"position":1,"eggsPerTray":30,"trays":2},{"sourceId":"b","name":"Cliente B","phone":"81999990000","address":"Rua B","weekday":4,"position":2,"eggsPerTray":20,"trays":1}]',gen_random_uuid())->>'created','2','mesmo lote com novo request retorna resultado sem duplicar');
select is((select count(*)from public.customer_sources where source='fonte-teste'),2::bigint,'repetir lote não duplica mapeamentos');
select throws_ok($$select public.commit_customer_import('61000000-0000-0000-0000-000000000001','[]',gen_random_uuid())$$,'PT409','BATCH_CONFLICT','lote não aceita payload diferente');
select throws_ok($$select public.prepare_customer_import(gen_random_uuid(),'fonte-teste','[{"sourceId":"ruim","name":"Inválido","address":"Rua","weekday":4,"position":1,"eggsPerTray":15,"trays":1},{"sourceId":"ruim","name":"Inválido","address":"Rua","weekday":4,"position":1,"eggsPerTray":30,"trays":-1}]')$$,'22023','INVALID_INPUT','grupo com linha negativa não é preparado parcialmente');
select throws_ok($$select public.prepare_customer_import(gen_random_uuid(),'fonte-teste','[{"sourceId":"ruim","name":"A","address":"Rua","weekday":4,"position":1,"eggsPerTray":15,"trays":1},{"sourceId":"ruim","name":"B","address":"Rua","weekday":4,"position":1,"eggsPerTray":30,"trays":1}]')$$,'22023','INVALID_INPUT','dados conflitantes bloqueiam grupo');
select throws_ok($$select public.prepare_customer_import(gen_random_uuid(),'fonte-teste','[{"sourceId":"ruim","name":"A","address":"Rua","weekday":4,"position":1,"eggsPerTray":15,"trays":1,"priceCents":1}]')$$,'22023','INVALID_INPUT','preço arbitrário não é aceito');
select public.prepare_customer_import('61000000-0000-0000-0000-000000000002','outra-fonte','[{"sourceId":"a","name":"Outro cliente","address":"Rua","weekday":3,"position":1,"eggsPerTray":30,"trays":1}]');
select is(public.commit_customer_import('61000000-0000-0000-0000-000000000002','[{"sourceId":"a","name":"Outro cliente","address":"Rua","weekday":3,"position":1,"eggsPerTray":30,"trays":1}]',gen_random_uuid())->>'created','1','mesmo ID em fonte diferente não une clientes');
select public.prepare_customer_import('61000000-0000-0000-0000-000000000003','fonte-teste','[{"sourceId":"a","name":"A alterado","address":"Rua nova","weekday":4,"position":1,"eggsPerTray":30,"trays":3}]');
reset role;
insert into public.customer_prices values((select customer_id from public.customer_sources where source='fonte-teste'and source_id='a'),'30000000-0000-0000-0000-000000000030',3000);
set local role authenticated;
select is(public.commit_customer_import('61000000-0000-0000-0000-000000000003','[{"sourceId":"a","name":"A alterado","address":"Rua nova","weekday":4,"position":1,"eggsPerTray":30,"trays":3}]',gen_random_uuid())->>'updated','1','nova conferência atualiza pelo mapeamento');
select is((select price_cents from public.customer_prices where customer_id=(select customer_id from public.customer_sources where source='fonte-teste'and source_id='a')),3000,'importação conserva preço negociado existente');
select public.prepare_customer_import('61000000-0000-0000-0000-000000000004','fonte-teste','[{"sourceId":"a","name":"A sobrescrito","address":"Rua velha","weekday":4,"position":1,"eggsPerTray":30,"trays":1}]');
select public.save_customer((select customer_id from public.customer_sources where source='fonte-teste'and source_id='a'),2,'{"name":"Edição concorrente","address":"Rua concorrente","phone":null,"active":true,"weekday":4,"position":1}','[{"productId":"30000000-0000-0000-0000-000000000030","trays":4}]','[]',gen_random_uuid());
select throws_ok($$select public.commit_customer_import('61000000-0000-0000-0000-000000000004','[{"sourceId":"a","name":"A sobrescrito","address":"Rua velha","weekday":4,"position":1,"eggsPerTray":30,"trays":1}]',gen_random_uuid())$$,'PT409','VERSION_CONFLICT','conferência antiga não sobrescreve edição concorrente');
select is((select name from public.customers where id=(select customer_id from public.customer_sources where source='fonte-teste'and source_id='a')),'Edição concorrente','conflito preserva cadastro atual');
select public.generate_week('2042-01-06',gen_random_uuid());
select set_config('test.settings_version',public.get_operational_settings()->>'version',true);
select is(public.save_operational_settings((public.get_operational_settings()->>'version')::int,'{"driverId":"60000000-0000-0000-0000-000000000002","vehicle":{"id":"63000000-0000-0000-0000-000000000001","name":"Veículo fictício"},"locations":[{"id":"64000000-0000-0000-0000-000000000001","name":"Origem fictícia","address":"Endereço incompleto","confirmed":false}],"days":[{"weekday":1,"originId":"64000000-0000-0000-0000-000000000001"},{"weekday":2,"originId":"64000000-0000-0000-0000-000000000001"},{"weekday":3},{"weekday":4},{"weekday":5}]}','62000000-0000-0000-0000-000000000002')->>'version',((current_setting('test.settings_version'))::integer+1)::text,'dona salva configuração versionada');
select is((select address from public.route_template_stops where template_id=(select id from public.route_templates where weekday=1)and kind='departure'),null::text,'endereço incompleto continua pendente');
select is((select count(*)from public.route_template_stops where template_id in(select id from public.route_templates where weekday in(2,3))and kind='arrival'),0::bigint,'não inventa chegada terça e quarta');
select is((select driver_id from public.route_runs where service_date='2042-01-06'),null::uuid,'configuração não reescreve execução existente');
select public.generate_week('2042-01-13',gen_random_uuid());
select is((select driver_id from public.route_runs where service_date='2042-01-13'),'60000000-0000-0000-0000-000000000002'::uuid,'próxima geração usa motorista configurado');
select throws_ok($$select public.save_operational_settings(1,'{}',gen_random_uuid())$$,'PT409','VERSION_CONFLICT','configuração antiga não sobrescreve');
select throws_ok($$update public.operational_settings set version=99$$,'42501',null,'escrita direta não contorna versão');
reset role;
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.prepare_customer_import(gen_random_uuid(),'x','[]')$$,'42501','FORBIDDEN','motorista não prepara importação');
select throws_ok($$select public.commit_customer_import(gen_random_uuid(),'[]',gen_random_uuid())$$,'42501','FORBIDDEN','motorista não confirma importação');
select throws_ok($$select public.get_operational_settings()$$,'42501','FORBIDDEN','motorista não lê configurações');
select * from finish();
rollback;
